  ('150832064255784740', 'Prima Doll', 2022, 'Animation, Drama, Sci-Fi & Fantasy', null, null, 'Azumi Waki, Tomori Kusunoki, Miyu Tomita, Yuki Nakashima, Akari Kito, Tomoyo Kurosawa, Ayumu Murase, Misaki Kuno', 'TV-14', 'Just a few years prior, automata served as weapons in the great war. Now that the war has ended, these machines with human hearts search for their place in an unfamiliar, peaceful world — and their search begins at the Kuronekotei café.', 'Just a few years prior, automata served as weapons in the great war. Now that the war has ended, these machines with human hearts search for their place in an unfamiliar, peaceful world — and their search begins at the Kuronekotei café.', 'https://image.tmdb.org/t/p/w500/z8DjN9RlcMy4WIQpgtbFqp9dLtM.jpg', 1, 'tmdb:tv:156450'),
  ('744211014636076477', 'Primal', 2019, 'Action & Adventure, Animation', 'Genndy Tartakovsky', null, 'Aaron LaPlante', 'TV-14', 'A caveman forms a bond with a dinosaur as they struggle to survive in a hostile world.', 'A caveman forms a bond with a dinosaur as they struggle to survive in a hostile world.', 'https://image.tmdb.org/t/p/w500/mf12pRakr3eYdJtv6klQtoznnbU.jpg', 3, 'tmdb:tv:89456'),
